  $condition=['and',['w.reconciliation_state'=>'delivered']];if($filters['status']!=='')$condition[]=['w.employment_status'=>$filters['status']];if($filters['availability']!=='')$condition[]=$activeTabIds===[]?new Expression($filters['availability']==='assigned'?'0=1':'1=1'):[$filters['availability']==='assigned'?'in':'not in','w.installer_tab_id',$activeTabIds];if($filters['q']!==''){$search=['or',['like','w.fio',$filters['q']]];if($filters['tab']!=='')$search[]=['like',new Expression('CAST([[w.installer_tab_id]] AS CHAR)'),$filters['tab']];$condition[]=$search;}
  $total=(int)(new Query())->from(['w'=>$catalog])->where($condition)->count('*',$this->db);$pages=max(1,(int)ceil($total/self::PAGE_SIZE));if($filters['page']>$pages)throw new \OutOfRangeException('Directory page unavailable.');
  $rows=(new Query())->addSelect(['w.installer_tab_id','w.fio','w.position','w.employment_status','w.dismissal_effective_at','w.workforce_source','w.workforce_source_updated_at'])->from(['w'=>$catalog])->where($condition)->orderBy(['w.fio'=>SORT_ASC,'w.installer_tab_id'=>SORT_ASC])->limit(self::PAGE_SIZE)->offset(($filters['page']-1)*self::PAGE_SIZE)->all($this->db);
  foreach($rows as&$row){$this->validateInstaller($row);$assignments=array_values($allAssignments[(int)$row['installer_tab_id']]??[]);usort($assignments,static fn(array$a,array$b):int=>[(int)$a['object_id'],(string)$a['valid_from']]<=>[(int)$b['object_id'],(string)$b['valid_from']]);$row['assignments']=$assignments;}unset($row);$totalCatalog=(int)($summary['total']??0);$working=(int)($summary['working']??0);return['summary'=>['total'=>$totalCatalog,'working'=>$working,'dismissed'=>$totalCatalog-$working,'assigned'=>(int)($summary['assigned']??0),'updatedAt'=>$summary['updated_at']],'rows'=>$rows,'filters'=>$filters+['total'=>$total,'pages'=>$pages]];
 }
 private function validateInstaller(array$row):void{if((int)($row['installer_tab_id']??0)<1||trim((string)($row['fio']??''))===''||trim((string)($row['position']??''))===''||!in_array($row['employment_status']??null,['employed','dismissed'],true)||!$this->validTimestamp((string)($row['workforce_source_updated_at']??''))||(($row['dismissal_effective_at']??null)!==null&&!$this->validDate((string)$row['dismissal_effective_at'])))throw new \RuntimeException('Directory row unavailable.');}
 private function validateAssignment(array$row):void{if((int)($row['installer_tab_id']??0)<1||(int)($row['object_id']??0)<1||trim((string)($row['registration_number']??''))===''||trim((string)($row['address']??''))===''||!$this->validDate((string)($row['valid_from']??'')))throw new \RuntimeException('Directory assignment unavailable.');}
 private function validateNativeApplication(array$row):void{try{$snapshot=json_decode((string)($row['selected_snapshot_json']??''),true,512,JSON_THROW_ON_ERROR);}catch(\Throwable){throw new \RuntimeException('Directory assignment unavailable.');}if((int)($row['application_sequence']??0)<1||(int)($row['application_object_id']??0)!==(int)($row['object_id']??0)||!is_array($snapshot)||array_keys($snapshot)!==['selectedInstallers','selectedEngineer'])throw new \RuntimeException('Directory assignment unavailable.');try{YiiObjectCardApplicationIntegrity::validateComposition(array_replace($row,['object_id'=>$row['application_object_id']]),$snapshot);}catch(\Throwable){throw new \RuntimeException('Directory assignment unavailable.');}}
 private function validTimestamp(string$value):bool{try{new \DateTimeImmutable($value);return$value!=='';}catch(\Throwable){return false;}}
 private function validDate(string$value):bool{$date=\DateTimeImmutable::createFromFormat('!Y-m-d',$value,new \DateTimeZone('Europe/Moscow'));return$date!==false&&$date->format('Y-m-d')===$value;}
}
